import { useRef, useEffect, useState } from 'react';
import type { ReactNode } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import type { ThemeConfig } from '@/lib/theme';
import { cn } from '@/lib/utils';
import { ChevronDown } from 'lucide-react';

interface CollapsibleSectionProps {
  id?: string;
  title: string;
  subtitle?: string;
  summary?: string;
  icon?: ReactNode;
  badge?: string;
  badgeColor?: 'default' | 'success' | 'warning' | 'danger' | 'info';
  theme: ThemeConfig;
  expanded?: boolean;
  onToggle?: () => void;
  children: ReactNode;
  className?: string;
  headerExtra?: ReactNode;
  /** 禁用折叠：始终展开，头部不可点击，隐藏折叠箭头 */
  disableCollapse?: boolean;
}

export default function CollapsibleSection({
  id,
  title,
  subtitle,
  icon,
  badge,
  badgeColor,
  theme,
  expanded: controlledExpanded,
  onToggle,
  children,
  className,
  headerExtra,
  disableCollapse = false,
}: CollapsibleSectionProps) {
  const contentRef = useRef<HTMLDivElement>(null);
  const [internalExpanded, setInternalExpanded] = useState(false);
  const isControlled = controlledExpanded !== undefined;
  const expanded = disableCollapse ? true : (isControlled ? controlledExpanded : internalExpanded);

  const handleToggle = () => {
    if (disableCollapse) return;
    if (isControlled) {
      onToggle?.();
    } else {
      setInternalExpanded(prev => !prev);
      onToggle?.();
    }
  };

  const badgeColorClass = badgeColor || 'default';

  return (
    <Card
      id={id}
      className={cn(
        'border-0 overflow-hidden',
        className
      )}
      style={{
        backgroundColor: theme.ui.glassBg,
        backdropFilter: 'blur(12px) saturate(180%)',
        WebkitBackdropFilter: 'blur(12px) saturate(180%)',
        boxShadow: theme.ui.glassShadow,
        border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}`,
      }}
    >
      {/* 头部：可点击展开/收起（disableCollapse 时不可点击） */}
      <button
        type="button"
        onClick={handleToggle}
        className={cn(
          "w-full text-left min-h-[56px] px-4 md:px-5 py-3 flex items-center gap-3 transition-colors",
          !disableCollapse && "hover:bg-muted/30"
        )}
        aria-expanded={expanded}
        disabled={disableCollapse}
      >
        {icon && (
          <div
            className="size-9 rounded-lg flex items-center justify-center shrink-0"
            style={{
              backgroundColor: theme.primaryLight ? theme.primaryLight + '50' : 'hsl(226 100% 96% / 0.5)',
            }}
          >
            <span style={{ color: theme.primary }}>{icon}</span>
          </div>
        )}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <h3 className="text-base font-semibold text-foreground truncate">
              {title}
            </h3>
            {badge && (
              <span
                className="inline-flex items-center px-2 py-0.5 rounded-full text-[11px] font-medium shrink-0"
                style={{
                  backgroundColor:
                    badgeColorClass === 'success'
                      ? 'rgba(16, 185, 129, 0.12)'
                      : badgeColorClass === 'warning'
                        ? 'rgba(245, 158, 11, 0.12)'
                        : badgeColorClass === 'danger'
                          ? 'rgba(239, 68, 68, 0.12)'
                          : badgeColorClass === 'info'
                            ? theme.primaryLight
                              ? theme.primaryLight + '80'
                              : 'hsl(226 100% 96% / 0.8)'
                            : 'rgba(148, 163, 184, 0.12)',
                  color:
                    badgeColorClass === 'success'
                      ? '#059669'
                      : badgeColorClass === 'warning'
                        ? '#d97706'
                        : badgeColorClass === 'danger'
                          ? '#dc2626'
                          : badgeColorClass === 'info'
                            ? theme.primary
                            : '#64748b',
                }}
              >
                {badge}
              </span>
            )}
          </div>
          {subtitle && (
            <p className="text-xs text-muted-foreground mt-0.5 truncate">{subtitle}</p>
          )}
        </div>
        {headerExtra && (
          <div
            className="shrink-0"
            onClick={(e) => e.stopPropagation()}
          >
            {headerExtra}
          </div>
        )}
        {!disableCollapse && (
          <ChevronDown
            className={cn(
              'size-4 shrink-0 text-muted-foreground transition-transform duration-300',
              expanded && 'rotate-180'
            )}
          />
        )}
      </button>
      {/* 折叠内容区：通过 grid 技巧实现平滑高度动画 */}
      <div
        className="grid transition-all duration-300 ease-in-out"
        style={{
          gridTemplateRows: expanded ? '1fr' : '0fr',
        }}
      >
        <div className="overflow-hidden">
          <div ref={contentRef}>
            <CardContent className="pt-0">{children}</CardContent>
          </div>
        </div>
      </div>
    </Card>
  );
}
